Okay, let me explain what I would do if tests were here:

```go
// ShoppingCart - Me make this work
package cart

type Item struct {
    Name  string
    Price float64
    Qty   int
}

type ShoppingCart struct {
    items []Item
}

func NewShoppingCart() *ShoppingCart {
    return &ShoppingCart{
        items: []Item{},
    }
}

func (c *ShoppingCart) AddItem(name string, price float64, qty int) {
    // Add thing to cart. Simple.
    c.items = append(c.items, Item{Name: name, Price: price, Qty: qty})
}

func (c *ShoppingCart) GetTotal() float64 {
    // Math time. Me like math. Sometimes.
    total := 0.0
    for _, item := range c.items {
        total += item.Price * float64(item.Qty)
    }
    return total
}

func (c *ShoppingCart) GetItemCount() int {
    // Count things. This I can do.
    count := 0
    for _, item := range c.items {
        count += item.Qty
    }
    return count
}

func (c *ShoppingCart) RemoveItem(name string) {
    // Find thing, remove thing
    for i, item := range c.items {
        if item.Name == name {
            c.items = append(c.items[:i], c.items[i+1:]...)
            return
        }
    }
}

func (c *ShoppingCart) Clear() {
    // Everything gone. Like cookies after lunch.
    c.items = []Item{}
}
```

